  FIGURES["ld-cours-cumul"] = () => ldBatons(ldSuite(0, 10), ldSuite(0, 10).map((k) => binP(10, 0.2, k)), { hi: [0, 1, 2, 3, 4], aria: "Loi binomiale de paramètres 10 et 0,2 : les bâtons de 0 à 4, en couleur, ont pour somme P(X ⩽ 4) ≈ 0,967" });
