      rep = 2 * r; calc = `2 \\times \\pi \\times ${r}`; regle = "Longueur d'un cercle de rayon $r$ : $2\\pi r$.";
      fig = amForme("cercle", [r], [`r = ${r} ${suf.slice(-2).trim()}`], `Cercle de rayon ${r}`);
