      ys = [rand(-4, 4)]; for (let k = 1; k < n; k++) { let y; do { y = rand(-4, 4); } while (Math.abs(y - ys[k - 1]) < 2 || (k > 1 && Math.sign(y - ys[k - 1]) === Math.sign(ys[k - 1] - ys[k - 2]))); ys.push(y); }
