    const xs = clPas(2 * X, 8), ys = clPas(Y, 6), yb = Math.min(Math.sqrt(Y - ys * 0.1), X - 0.15);
    const o = { xmin: -X, xmax: X, ymin: Math.min(-0.8 * ys, k - 0.8 * ys), ymax: Y, xstep: xs, ystep: ys, xetiq: 2 * X / xs > 8 ? 2 * xs : xs, h: 250,
      curves: [{ f: (x) => x * x, a: -yb, b: yb, closed: false, label: "y = x²", lx: 0.55 * yb, dx: 52, dy: 6 }],
      aria: "Parabole d'équation y = x² dans un repère quadrillé" };
