  FIGURES["fa-cours-variations"] = () => faRep([{ m: 1.5, p: -1, label: "m > 0" }, { m: -0.5, p: 2, label: "m < 0" }], [], "Deux droites : celle de coefficient directeur positif monte, celle de coefficient directeur négatif descend");
  FIGURES["fa-cours-encadrer"] = () => faEncadre(-3, 1, 2, 5, "Droite y = −3x + 1 pour x entre 2 et 5 : les images sont entre α et β, dans l'ordre inverse car la fonction est décroissante");
