  FIGURES["fa-meth-lire"] = () => faRep([{ m: 2 / 3, p: -1, label: "d" }], [{ x: 0, y: -1, label: "(0 ; −1)" }, { x: 3, y: 1 }], "Droite d qui coupe l'axe des ordonnées en −1 ; en avançant de 3 vers la droite, on monte de 2", [{ x1: 0, y1: -1, x2: 3, y2: -1, c: 1, label: "+3" }, { x1: 3, y1: -1, x2: 3, y2: 1, c: 1, label: "+2" }]);
  FIGURES["fa-meth-signe"] = () => tabsigne(["−∞", "3", "+∞"], [{ nom: "−2x + 6", cases: ["+", "0", "-"] }]);
