      const [ctx, u, uu] = pick([["une course de taxi-brousse", "km", "kilomètre"], ["la location d'un scooter à Petite-Terre", "jours", "jour"], ["la location d'un kayak à N'Gouja", "heures", "heure"], ["un trajet en bus jusqu'au lycée de Sada", "km", "kilomètre"]]);
