    br(x1 + 10, yA, x2, ys[0], p[2]); br(x1 + 10, yA, x2, ys[1], p[3]);
    br(x1 + 10, yN, x2, ys[2], p[4]); br(x1 + 10, yN, x2, ys[3], p[5]);
