    let s = `<svg class="graph" viewBox="0 0 320 ${H}" role="img" aria-label="Plaque de ${L} cm sur ${l} cm dont on découpe un carré de côté x à chaque coin ; le fond mesure ${L} − 2x sur ${l} − 2x">`;
    s += `<rect x="${o}" y="10" width="${Lp}" height="${lp}" style="fill:var(--lagon-pale);stroke:var(--lagon);stroke-width:1.6"/>`;
