  const piNet = (errs, rep, tol) => errs.filter((e, i, T) => isFinite(e.valeur) && Math.abs(e.valeur - rep) > (tol || 1e-9) && T.findIndex((f) => Math.abs(f.valeur - e.valeur) < 1e-9) === i);

