        const [f, k, d, v, autre] = pick([["cos", 0, 1, "1", "2\\pi"], ["sin", 1, 2, "1", "\\dfrac{5\\pi}{2}"], ["cos", 1, 1, "-1", "-\\pi"], ["sin", -1, 2, "-1", "\\dfrac{3\\pi}{2}"], ["cos", 1, 2, "0", "-\\dfrac{\\pi}{2}"], ["sin", 0, 1, "0", "\\pi"], ["cos", 1, 3, VAL.h, "-\\dfrac{\\pi}{3}"], ["cos", 1, 4, VAL.r2, "-\\dfrac{\\pi}{4}"], ["cos", 1, 6, VAL.r3, "-\\dfrac{\\pi}{6}"], ["sin", 1, 6, VAL.h, "\\dfrac{5\\pi}{6}"], ["sin", 1, 4, VAL.r2, "\\dfrac{3\\pi}{4}"], ["sin", 1, 3, VAL.r3, "\\dfrac{2\\pi}{3}"]]);
