        const [f, v, g, cp] = pick([["cos", "1", "sin", "\\pi"], ["cos", "-1", "sin", "0"], ["sin", "1", "cos", "-\\dfrac{\\pi}{2}"], ["sin", "-1", "cos", "\\dfrac{\\pi}{2}"]]), sens = Math.random() < 0.5;
        const vAutre = { "\\pi": "-1", 0: "1", "-\\dfrac{\\pi}{2}": "-1", "\\dfrac{\\pi}{2}": "1" }[cp];
