    const arch = (P, e) => { let n = P.n0, c = P.c0; for (let k = 0; k < e; k++) { c = Math.sqrt(2 - Math.sqrt(4 - c * c)); n *= 2; } return { n, c, v: (n * c) / 2 }; };
