      const [obj, ou] = pick([["Une noix de coco", "tombe d'un cocotier de la plage de Moya"], ["Une mangue", "tombe d'un manguier à Combani"], ["Un fruit à pain", "tombe d'un arbre à Tsingoni"], ["Un caillou", "tombe d'une falaise du mont Choungui"], ["Une goyave", "tombe d'un goyavier à Bandrélé"], ["Une balle", "est lâchée du haut d'un immeuble de Mamoudzou"], ["Un jacquier", "laisse tomber un fruit à Dembéni"]]);
      const t0 = pick([0.5, 0.8, 1, 1.2, 1.5, 2, 2.5, 3]), v = +(9.8 * t0).toFixed(6), inv = Math.random() < 0.35;
