      const as = [1, 2, 3].filter((a) => Math.abs(f(a)) > 1e-9 && Number.isInteger(+(f(a) * 100).toFixed(6))), a = pick(as.length ? as : [1]), v = +f(a).toFixed(6), rep = typ === 0 ? v : -v;
      const [lo, hi] = ech(0, 3), st = d2Pas(hi - lo + 1);
