  // Deux courbes (f au-dessus ou en dessous de g) sur [a ; b], pour illustrer une inégalité
  function vrDeux(f, g, a, b, nf, ng, aria, pts) {
    const ys = []; for (let k = 0; k <= 60; k++) { const x = a + ((b - a) * k) / 60; ys.push(f(x), g(x)); }
    const lo = Math.min(...ys, 0), hi = Math.max(...ys, 0), st = d2Pas(hi - lo + 1);
    return graph({ xmin: Math.min(a, 0) - 0.4, xmax: Math.max(b, 0) + 0.4, ymin: lo - 0.4 * st, ymax: hi + 0.4 * st, ystep: st, h: 240, curves: [{ f, a, b, closed: false, label: nf, lx: b, dx: -6, dy: -8 }, { f: g, a, b, closed: false, label: ng, lx: b, dx: -6, dy: 16 }], points: pts || [], aria });
  }

