      const fausses = [concl(croix), `$\\vec{u} \\cdot \\vec{v} = ${v}$, donc ${v === 0 ? "ils ne sont pas orthogonaux" : "ils sont orthogonaux"}`, `$\\vec{u} \\cdot \\vec{v} = ${v}$, donc ils sont colinéaires`, concl(a * c - b * d)];
      const ch = melangeChoix(concl(v), fausses);
