  // Somme de termes [coefficient, facteur] écrite proprement ; num : facteurs numériques (« 2 \times 25 - 3 \times (-2) »)
  const scTermes = (L, num) => L.filter(([c]) => c).map(([c, f], k) => (c < 0 ? (k ? " - " : "-") : k ? " + " : "") + (num ? (Math.abs(c) === 1 ? par(f) : `${Math.abs(c)} \\times ${par(f)}`) : `${Math.abs(c) === 1 ? "" : Math.abs(c)}${f}`)).join("") || "0";
  // Erreurs typiques [valeur, message] : sans doublon, et loin de la réponse (à la tolérance près)
  const scErr = (rep, L, tol = 1e-9) => L.filter(([v], j) => isFinite(v) && Math.abs(v - rep) > tol && L.findIndex((x) => Math.abs(x[0] - v) <= tol) === j).map(([valeur, message]) => ({ valeur, message }));
  const scArr = (x, d) => x.toFixed(d).replace(".", "{,}"); // valeur arrondie écrite avec ses d décimales (10{,}0)
  const scFrac = (n, d) => `\\dfrac{${n}}{${d}}${pgcd(n, d) > 1 || n < 0 ? ` = ${frac(n, d)}` : ""}`; // fraction, puis sa forme simplifiée
  const scRac = (n) => (Number.isInteger(Math.sqrt(n)) ? `${Math.sqrt(n)}` : `\\sqrt{${n}}`); // √n, ou l'entier quand n est un carré
  const SC_PRENOMS = ["Anli", "Nassim", "Zaïnaba", "Fatima", "Moussa", "Awa", "Ibrahim", "Mariama", "Saïd", "Djamila", "Hamada", "Faïza", "Kamal", "Zalifa", "Ambdi", "Nasra", "Toiyb", "Roukia"];

  // Triangle à l'échelle : angle A (en degrés) au sommet n[0], c = n[0]n[1], b = n[0]n[2] ; o.t : étiquettes des côtés { c, b, a }
  // (a : côté opposé à n[0]) ; o.ang : étiquettes des angles [en n[0], en n[1], en n[2]] (« droit » : équerre) ; o.q : étiquettes
