      let nr = [-e[1], e[0]]; if (nr[0] * (m[0] - G[0]) + nr[1] * (m[1] - G[1]) < 0) nr = [-nr[0], -nr[1]];
      let x = m[0] + 9 * nr[0], y = m[1] + 15 * nr[1] + 4;
      const an = nr[0] > 0.45 ? "start" : nr[0] < -0.45 ? "end" : "middle", lw = String(T[nom]).length * 6.8, cx = () => (an === "start" ? x + lw / 2 : an === "end" ? x - lw / 2 : x);
