    const x0 = Math.min(0, P[3][0]), w = Math.max(P[1][0], P[2][0]) - x0, k = Math.min(200 / w, 120 / P[3][1]), H = Math.round(P[3][1] * k + 74 + L);
    const S = P.map(([x, y]) => [scF((320 - w * k) / 2 + (x - x0) * k), scF(H - L - 36 - y * k)]), T = o.t || {}, q = o.q || [];
