  FIGURES["sc-cours-python"] = () => graph({ xmin: -1.4, xmax: 5.4, ymin: -1.4, ymax: 3.4, h: 230, fleches: [{ x1: 0, y1: 0, x2: 4, y2: 0, label: "u" }, { x1: 0, y1: 0, x2: 2, y2: 2, c: 1, label: "v" }], points: [{ x: 0, y: 0, label: "A", gauche: true }, { x: 4, y: 0, label: "B(4 ; 0)" }, { x: 2, y: 2, label: "C(2 ; 2)" }], aria: "Les vecteurs u = AB(4 ; 0) et v = AC(2 ; 2) partent du premier point A : la fonction angle calcule l'angle BAC, ici 45°" });
  FIGURES["sc-qcm-60"] = () => scTri({ A: 60, c: 3, b: 4, t: { c: "3", b: "4", a: "?" }, ang: ["60°"], q: ["a"], aria: "Triangle ABC avec AB = 3, AC = 4 et un angle de 60° en A ; BC est cherché" });
  FIGURES["sc-qcm-120"] = () => scTri({ A: 120, c: 2, b: 3, t: { c: "2", b: "3", a: "?" }, ang: ["120°"], q: ["a"], aria: "Triangle ABC avec AB = 2, AC = 3 et un angle de 120° en A ; BC est cherché" });
  FIGURES["sc-qcm-534"] = () => scTri({ A: scDeg(0.6), c: 5, b: 3, t: { c: "5", b: "3", a: "4" }, ang: ["?"], q: ["A"], aria: "Triangle ABC avec AB = 5, AC = 3 et BC = 4 ; l'angle en A est cherché" });
  FIGURES["sc-qcm-pirogue"] = () => scTri({ n: ["P", "A", "B"], A: 60, c: 2, b: 2, t: { c: "2 km", b: "2 km", a: "?" }, ang: ["60°"], q: ["a"], lagon: true, aria: "Depuis une pirogue P, deux îlots A et B à 2 km chacun, avec un angle de 60° entre les deux visées ; AB est cherchée" });
  FIGURES["sc-qcm-normes"] = () => scPara(2, 3, scDeg(0.25), { vec: true, diag: ["AC"], t: { AB: "u", AD: "v", AC: "u + v" }, legende: "‖u‖ = 2 ; ‖v‖ = 3 ; ‖u + v‖ = 4", aria: "Parallélogramme construit sur u et v, de normes 2 et 3 ; la diagonale u + v a pour norme 4" });
  FIGURES["sc-qcm-para"] = () => scPara(5, 3, 60, { diag: ["AC"], t: { AB: "5", AD: "3", AC: "7" }, aria: "Parallélogramme ABCD avec AB = 5, AD = 3 et la diagonale AC = 7" });
  FIGURES["sc-qcm-para-bd"] = () => scPara(5, 3, 60, { diag: ["AC", "BD"], t: { AB: "5", AD: "3", AC: "7", BD: "?" }, q: ["BD"], aria: "Parallélogramme ABCD avec AB = 5, AD = 3 et AC = 7 ; la diagonale BD est cherchée" });
  FIGURES["sc-qcm-repere"] = () => repere([[1, 2, "A(1 ; 2)"], [5, -2, "B(5 ; −2)"]], []).replace('aria-label="Points placés dans un repère"', 'aria-label="Points A(1 ; 2) et B(5 ; −2) dans un repère orthonormé"');
  FIGURES["sc-meth-alkashi"] = () => scTri({ A: 60, c: 5, b: 8, t: { c: "c = 5", b: "b = 8", a: "a = ?" }, ang: ["60°"], q: ["a"], aria: "Triangle ABC avec c = AB = 5, b = AC = 8 et un angle de 60° en A ; a = BC est cherché" });

  // Normes entières et produit scalaire possible : |u · v| < ‖u‖ × ‖v‖, et non nul
  const scDonnees = () => { const nu = rand(1, 6), nv = rand(1, 6), m = Math.min(nu * nv - 1, 9); return m < 1 ? scDonnees() : [nu, nv, randNZ(-m, m)]; };
  const scComb = (a, b) => scTermes([[a, "\\vec{u}"], [b, "\\vec{v}"]]);
  const SC_UV = "\\,\\vec{u} \\cdot \\vec{v}", SC_U2 = "\\|\\vec{u}\\|^2", SC_V2 = "\\|\\vec{v}\\|^2";

  GEN["sc-bilineaire"] = function () {
    const [nu, nv, uv] = scDonnees(), u2 = nu * nu, v2 = nv * nv, t = Math.random();
    const don = `On sait que $\\|\\vec{u}\\| = ${nu}$, $\\|\\vec{v}\\| = ${nv}$ et $\\vec{u} \\cdot \\vec{v} = ${uv}$.`;
    const base = { mode: "nombre", prefixe: "Résultat :", figure: psAngleFig(nu, nv, Math.round(scDeg(uv / (nu * nv))), "θ") };
    if (t < 0.38) {
      // (au + bv) · (cu + dv)
      let a, b, c, d;
      do { a = rand(-3, 3); b = rand(-3, 3); c = rand(-3, 3); d = rand(-3, 3); } while ((!a && !b) || (!c && !d) || [a, b, c, d].filter((x) => x).length < 3 || (a === c && b === d) || (a === -c && b === -d));
      const X = a * c, Y = a * d + b * c, Z = b * d, rep = X * u2 + Y * uv + Z * v2, f1 = scComb(a, b), f2 = scComb(c, d);
      const ex = `${a && b ? `(${f1})` : f1} \\cdot ${(c && d) || c < 0 || d < 0 ? `(${f2})` : f2}`, dev = scTermes([[X, SC_U2], [Y, SC_UV], [Z, SC_V2]]);
      return { ...base, enonce: `${don} Calcule $${ex}$.`, attendu: rep,
        erreurs: scErr(rep, [[X * u2 + Z * v2, "Tu as oublié des termes croisés : développe tous les produits, comme $(a + b)(c + d) = ac + ad + bc + bd$."], [X * nu + Y * uv + Z * nv, "$\\vec{u} \\cdot \\vec{u} = \\|\\vec{u}\\|^2$ : il faut élever les normes au carré."], [X * u2 + a * d * uv + Z * v2, "Il y a deux termes croisés, $\\vec{u} \\cdot \\vec{v}$ et $\\vec{v} \\cdot \\vec{u}$, égaux par symétrie : additionne-les."]]),
        aides: ["Développe comme $(a + b)(c + d) = ac + ad + bc + bd$ : le produit scalaire est bilinéaire.", "Remplace $\\vec{u} \\cdot \\vec{u}$ par $\\|\\vec{u}\\|^2$ et $\\vec{v} \\cdot \\vec{v}$ par $\\|\\vec{v}\\|^2$, puis regroupe $\\vec{v} \\cdot \\vec{u} = \\vec{u} \\cdot \\vec{v}$ (symétrie).", `Tu dois obtenir $${dev}$ : remplace par les valeurs.`],
        solution: `$${ex} = ${scTermes([[a * c, SC_U2], [a * d, SC_UV], [b * c, "\\,\\vec{v} \\cdot \\vec{u}"], [b * d, SC_V2]])}$\n\n$= ${dev} = ${scTermes([[X, u2], [Y, uv], [Z, v2]], true)} = ${rep}$.` };
    }
    if (t < 0.68) {
      // ‖au + bv‖²
      const a = pick([1, 1, 2, 3]), b = pick([1, -1, 2, -2, 3, -3]), rep = a * a * u2 + 2 * a * b * uv + b * b * v2, w = scComb(a, b);
      const dev = scTermes([[a * a, SC_U2], [2 * a * b, SC_UV], [b * b, SC_V2]]);
      return { ...base, enonce: `${don} Calcule $\\|${w}\\|^2$.`, attendu: rep,
        erreurs: scErr(rep, [[a * a * u2 + a * b * uv + b * b * v2, "Il manque le double produit : comme $(x + y)^2 = x^2 + 2xy + y^2$, le terme croisé est multiplié par $2$."], [a * a * u2 + b * b * v2, "Tu as oublié le terme croisé en $\\vec{u} \\cdot \\vec{v}$ : il n'est nul que si les vecteurs sont orthogonaux."], [a * u2 + 2 * a * b * uv + Math.abs(b) * v2, "Les coefficients sortent au carré : $\\|k\\vec{u}\\|^2 = k^2\\,\\|\\vec{u}\\|^2$."]]),
        aides: [`$\\|${w}\\|^2 = (${w}) \\cdot (${w})$ : développe.`, "Comme $(x + y)^2 = x^2 + 2xy + y^2$, sans oublier le double produit.", `Tu dois obtenir $${dev}$.`],
        solution: `$\\|${w}\\|^2 = (${w}) \\cdot (${w}) = ${dev}$\n\n$= ${scTermes([[a * a, u2], [2 * a * b, uv], [b * b, v2]], true)} = ${rep}$.` };
    }
    if (t < 0.82) {
      // (au + bv) · (au − bv)
      const a = pick([1, 1, 2, 3]), b = pick([1, 1, 2, 3]), rep = a * a * u2 - b * b * v2, p = scComb(a, b), m = scComb(a, -b);
      const fin = scTermes([[a * a, SC_U2], [-b * b, SC_V2]]);
      return { ...base, enonce: `${don} Calcule $(${p}) \\cdot (${m})$.`, attendu: rep,
        erreurs: scErr(rep, [[a * a * u2 + b * b * v2, "Attention au signe : comme $(x + y)(x - y) = x^2 - y^2$, on soustrait."], [a * u2 - b * v2, "Les coefficients sortent au carré : $(k\\vec{u}) \\cdot (k\\vec{u}) = k^2\\,\\|\\vec{u}\\|^2$."], ...(a === 1 && b === 1 ? [[(nu - nv) ** 2, "$\\|\\vec{u}\\|^2 - \\|\\vec{v}\\|^2$ n'est pas égal à $(\\|\\vec{u}\\| - \\|\\vec{v}\\|)^2$."]] : []), [a * a * u2 - 2 * a * b * uv - b * b * v2, "Les termes croisés s'éliminent : l'un est précédé de $+$, l'autre de $-$."]]),
        aides: ["Développe comme $(x + y)(x - y)$.", "Les termes croisés en $\\vec{u} \\cdot \\vec{v}$ s'éliminent.", `Il reste $${fin}$.`],
        solution: `$(${p}) \\cdot (${m}) = ${scTermes([[a * a, SC_U2], [-a * b, SC_UV], [a * b, "\\,\\vec{v} \\cdot \\vec{u}"], [-b * b, SC_V2]])} = ${fin}$\n\n$= ${scTermes([[a * a, u2], [-b * b, v2]], true)} = ${rep}$.` };
    }
    // Orthogonalité : (u + kv) · (pu + qv) = 0
    let p, q, N, D;
    do { p = pick([1, 1, 2, -1]); q = randNZ(-2, 2); N = p * u2 + q * uv; D = p * uv + q * v2; } while (!D || !N);
    const k = -N / D, w = scComb(p, q), kD = `${D < 0 ? "-" : "+"} ${Math.abs(D) === 1 ? "" : Math.abs(D)}k`;
    return { ...base, enonce: `${don} Pour quelle valeur du réel $k$ les vecteurs $\\vec{u} + k\\vec{v}$ et $${w}$ sont-ils orthogonaux ? Donne la valeur exacte (entier ou fraction).`,
      prefixe: "$k =$", attendu: k,
      erreurs: [...scErr(k, [[N / D, "Attention au signe en isolant $k$."], [-D / N, "Tu as inversé le quotient en isolant $k$."]]), ...d2Approx(k)],
      aides: ["Deux vecteurs sont orthogonaux si et seulement si leur produit scalaire est nul.", `Développe $(\\vec{u} + k\\vec{v}) \\cdot (${w})$ et remplace par les valeurs.`, `Tu obtiens $${N} ${kD} = 0$ : isole $k$.`],
      solution: `$(\\vec{u} + k\\vec{v}) \\cdot (${w}) = ${scTermes([[p, SC_U2], [q, SC_UV]])} + k\\left(${scTermes([[p, SC_UV], [q, SC_V2]])}\\right) = ${N} ${kD}$.\n\nLes vecteurs sont orthogonaux si et seulement si ce produit scalaire est nul : $k = ${frac(-N, D)}$.` };
  };

  GEN["sc-normes"] = function () {
    const t = Math.random();
    const fig = (nu, nv, uv, diag, lab) => scPara(nu, nv, scDeg(uv / (nu * nv)), { vec: true, diag: [diag], t: { AB: "u", AD: "v", [diag]: diag === "AC" ? "u + v" : "u − v" }, legende: `‖u‖ = ${nu} ; ‖v‖ = ${nv} ; ${lab}`, aria: `Parallélogramme construit sur u et v, de normes ${nu} et ${nv} ; la diagonale fléchée représente u ${diag === "AC" ? "+" : "−"} v` });
    if (t < 0.28) {
      // ‖u ± v‖² connu
      const [nu, nv, uv] = scDonnees(), plus = Math.random() < 0.5, S = nu * nu + nv * nv, s2 = S + (plus ? 2 : -2) * uv, sg2 = plus ? "+" : "-";
      return {
        enonce: `On sait que $\\|\\vec{u}\\| = ${nu}$, $\\|\\vec{v}\\| = ${nv}$ et $\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = ${s2}$. Calcule $\\vec{u} \\cdot \\vec{v}$.`,
        figure: fig(nu, nv, uv, plus ? "AC" : "BD", `‖u ${plus ? "+" : "−"} v‖² = ${s2}`),
        mode: "nombre", prefixe: "$\\vec{u} \\cdot \\vec{v} =$", attendu: uv,
        erreurs: scErr(uv, [[-uv, `Attention au signe : $\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = \\|\\vec{u}\\|^2 ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + \\|\\vec{v}\\|^2$.`], [2 * uv, "N'oublie pas de diviser par $2$."], [s2 - S, "Tu as oublié de diviser par $2$ (et vérifie le signe)."]]),
        aides: [`$\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = \\|\\vec{u}\\|^2 ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + \\|\\vec{v}\\|^2$.`, `$${s2} = ${nu * nu} ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + ${nv * nv}$.`, "Isole $\\vec{u} \\cdot \\vec{v}$."],
        solution: `$${s2} = ${S} ${sg2} 2\\,\\vec{u} \\cdot \\vec{v}$, donc $\\vec{u} \\cdot \\vec{v} = ${plus ? `\\dfrac{${s2} - ${S}}{2}` : `\\dfrac{${S} - ${s2}}{2}`} = ${uv}$.`
      };
    }
    if (t < 0.48) {
      // ‖u ± v‖ connu (pas au carré) : réponse entière ou demi-entière
      const nu = rand(2, 8), nv = rand(2, 8), s = rand(Math.abs(nu - nv) + 1, nu + nv - 1), plus = Math.random() < 0.6, sg2 = plus ? "+" : "-";
      const S = nu * nu + nv * nv, rep = (plus ? s * s - S : S - s * s) / 2;
      return {
        enonce: `On sait que $\\|\\vec{u}\\| = ${nu}$, $\\|\\vec{v}\\| = ${nv}$ et $\\|\\vec{u} ${sg2} \\vec{v}\\| = ${s}$. Calcule $\\vec{u} \\cdot \\vec{v}$.`,
        figure: fig(nu, nv, rep, plus ? "AC" : "BD", `‖u ${plus ? "+" : "−"} v‖ = ${s}`),
        mode: "nombre", prefixe: "$\\vec{u} \\cdot \\vec{v} =$", attendu: rep,
        erreurs: scErr(rep, [[(plus ? s - S : S - s) / 2, `Il faut élever la norme au carré : $\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = ${s}^2 = ${s * s}$.`], [2 * rep, "N'oublie pas de diviser par $2$."], [-rep, `Attention au signe : $\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = \\|\\vec{u}\\|^2 ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + \\|\\vec{v}\\|^2$.`]]),
        aides: [`Élève au carré : $\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = ${s * s}$.`, `$\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = \\|\\vec{u}\\|^2 ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + \\|\\vec{v}\\|^2$, donc $${s * s} = ${S} ${sg2} 2\\,\\vec{u} \\cdot \\vec{v}$.`, "Isole $\\vec{u} \\cdot \\vec{v}$."],
        solution: `$${s}^2 = ${nu}^2 ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + ${nv}^2$, soit $${s * s} = ${S} ${sg2} 2\\,\\vec{u} \\cdot \\vec{v}$, donc $\\vec{u} \\cdot \\vec{v} = ${plus ? `\\dfrac{${s * s} - ${S}}{2}` : `\\dfrac{${S} - ${s * s}}{2}`} = ${fr(rep)}$.`
      };
    }
    if (t < 0.62) {
      // Les deux carrés connus : u · v = (‖u + v‖² − ‖u − v‖²) / 4
      const [nu, nv, uv] = scDonnees(), S = nu * nu + nv * nv, p = S + 2 * uv, m = S - 2 * uv;
      return {
        enonce: `On sait que $\\|\\vec{u} + \\vec{v}\\|^2 = ${p}$ et $\\|\\vec{u} - \\vec{v}\\|^2 = ${m}$. Calcule $\\vec{u} \\cdot \\vec{v}$.`,
        figure: scPara(nu, nv, scDeg(uv / (nu * nv)), { vec: true, diag: ["AC", "BD"], t: { AB: "u", AD: "v", AC: "u + v", BD: "u − v" }, legende: `‖u + v‖² = ${p} ; ‖u − v‖² = ${m}`, aria: `Parallélogramme construit sur u et v : ses diagonales représentent u + v et u − v` }),
        mode: "nombre", prefixe: "$\\vec{u} \\cdot \\vec{v} =$", attendu: uv,
        erreurs: scErr(uv, [[(p - m) / 2, "Divise par $4$ : la différence des deux carrés vaut $4\\,\\vec{u} \\cdot \\vec{v}$."], [p - m, "Il reste à diviser par $4$."], [(m - p) / 4, "Attention à l'ordre : $\\|\\vec{u} + \\vec{v}\\|^2 - \\|\\vec{u} - \\vec{v}\\|^2 = 4\\,\\vec{u} \\cdot \\vec{v}$."]]),
        aides: ["Développe les deux carrés : $\\|\\vec{u} \\pm \\vec{v}\\|^2 = \\|\\vec{u}\\|^2 \\pm 2\\,\\vec{u} \\cdot \\vec{v} + \\|\\vec{v}\\|^2$.", "Soustrais les deux égalités : les carrés des normes disparaissent.", `Il reste $${p} - ${m} = 4\\,\\vec{u} \\cdot \\vec{v}$.`],
        solution: `En soustrayant les deux développements, $\\|\\vec{u} + \\vec{v}\\|^2 - \\|\\vec{u} - \\vec{v}\\|^2 = 4\\,\\vec{u} \\cdot \\vec{v}$, donc $\\vec{u} \\cdot \\vec{v} = \\dfrac{${p} - ${m}}{4} = ${uv}$.`
      };
    }
    if (t < 0.8) {
      // Angle entre u et v (valeur remarquable)
      const nu = rand(1, 8), nv = rand(1, 8), A = pick([60, 120, 90, 60, 120]), cs = { 60: 0.5, 90: 0, 120: -0.5 }[A], uv = nu * nv * cs, plus = Math.random() < 0.5, sg2 = plus ? "+" : "-";
      const s2 = nu * nu + nv * nv + (plus ? 2 : -2) * uv, cT = { 60: "\\dfrac{1}{2}", 90: "0", 120: "-\\dfrac{1}{2}" }[A];
      return {
        enonce: `On sait que $\\|\\vec{u}\\| = ${nu}$, $\\|\\vec{v}\\| = ${nv}$ et $\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = ${s2}$. Quelle est la mesure, en degrés, de l'angle entre $\\vec{u}$ et $\\vec{v}$ ?`,
        figureSolution: psAngleFig(nu, nv, A, `${A}°`),
        mode: "nombre", prefixe: "Angle :", suffixe: "°", attendu: A,
        erreurs: scErr(A, [[180 - A, "Attention au signe de $\\vec{u} \\cdot \\vec{v}$ : c'est aussi celui du cosinus de l'angle."], [uv, "Ça, c'est $\\vec{u} \\cdot \\vec{v}$ : divise-le par $\\|\\vec{u}\\| \\times \\|\\vec{v}\\|$ pour obtenir le cosinus de l'angle."], [cs, "Ça, c'est le cosinus de l'angle : reconnais une valeur remarquable."]]),
        aides: [`Développe : $\\|\\vec{u} ${sg2} \\vec{v}\\|^2 = \\|\\vec{u}\\|^2 ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + \\|\\vec{v}\\|^2$ et calcule $\\vec{u} \\cdot \\vec{v}$.`, "$\\vec{u} \\cdot \\vec{v} = \\|\\vec{u}\\| \\times \\|\\vec{v}\\| \\times \\cos \\theta$.", `Ici $\\vec{u} \\cdot \\vec{v} = ${fr(uv)}$ : calcule $\\cos \\theta$.`],
        solution: `$${s2} = ${nu * nu} ${sg2} 2\\,\\vec{u} \\cdot \\vec{v} + ${nv * nv}$, donc $\\vec{u} \\cdot \\vec{v} = ${fr(uv)}$. Puis $\\cos \\theta = \\dfrac{\\vec{u} \\cdot \\vec{v}}{\\|\\vec{u}\\| \\times \\|\\vec{v}\\|} = \\dfrac{${fr(uv)}}{${nu * nv}} = ${cT}$, donc $\\theta = ${A}°$.`
      };
    }
    // Parallélogramme : AC connu, AB · AD ou BD²
    let a, b, d; do { a = rand(3, 9); b = rand(2, 8); d = rand(Math.abs(a - b) + 1, a + b - 1); } while (d * d === a * a + b * b);
    const p = (d * d - a * a - b * b) / 2, bd2 = 2 * a * a + 2 * b * b - d * d, qBD = Math.random() < 0.5, pT = p < 0 ? `(${fr(p)})` : fr(p);
    const sol1 = `$\\overrightarrow{AC} = \\overrightarrow{AB} + \\overrightarrow{AD}$, donc $AC^2 = AB^2 + 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + AD^2$ : $${d * d} = ${a * a} + 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + ${b * b}$, d'où $\\overrightarrow{AB} \\cdot \\overrightarrow{AD} = \\dfrac{${d * d} - ${a * a} - ${b * b}}{2} = ${fr(p)}$.`;
    return {
      enonce: `$ABCD$ est un parallélogramme avec $AB = ${a}$, $AD = ${b}$ et $AC = ${d}$. ${qBD ? "Calcule $BD^2$." : "Calcule $\\overrightarrow{AB} \\cdot \\overrightarrow{AD}$."}`,
      figure: scPara(a, b, scDeg(p / (a * b)), { diag: qBD ? ["AC", "BD"] : ["AC"], t: { AB: `${a}`, AD: `${b}`, AC: `${d}`, BD: qBD ? "?" : undefined }, q: ["BD"], aria: `Parallélogramme ABCD avec AB = ${a}, AD = ${b} et la diagonale AC = ${d}${qBD ? " ; la diagonale BD est cherchée" : ""}` }),
      mode: "nombre", prefixe: qBD ? "$BD^2 =$" : "$\\overrightarrow{AB} \\cdot \\overrightarrow{AD} =$", attendu: qBD ? bd2 : p,
      erreurs: qBD ? scErr(bd2, [[d * d, "Les deux diagonales d'un parallélogramme n'ont pas la même longueur (sauf pour un rectangle)."], [a * a + b * b, "Ce serait vrai pour un rectangle ; ici $\\overrightarrow{AB} \\cdot \\overrightarrow{AD} \\neq 0$."], [p, "Ça, c'est $\\overrightarrow{AB} \\cdot \\overrightarrow{AD}$ : utilise-le pour calculer $BD^2$."]])
        : scErr(p, [[2 * p, "N'oublie pas de diviser par $2$."], [-p, "Attention au signe : $AC^2 = AB^2 + 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + AD^2$."]]),
      aides: ["$\\overrightarrow{AC} = \\overrightarrow{AB} + \\overrightarrow{AD}$ et $\\overrightarrow{DB} = \\overrightarrow{AB} - \\overrightarrow{AD}$ (règle du parallélogramme).", "Développe $AC^2 = \\|\\overrightarrow{AB} + \\overrightarrow{AD}\\|^2$ pour trouver $\\overrightarrow{AB} \\cdot \\overrightarrow{AD}$.", qBD ? "Puis $BD^2 = \\|\\overrightarrow{AB} - \\overrightarrow{AD}\\|^2 = AB^2 - 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + AD^2$." : `$${d * d} = ${a * a} + 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + ${b * b}$.`],
      solution: sol1 + (qBD ? `\n\n$\\overrightarrow{DB} = \\overrightarrow{AB} - \\overrightarrow{AD}$, donc $BD^2 = AB^2 - 2\\,\\overrightarrow{AB} \\cdot \\overrightarrow{AD} + AD^2 = ${a * a} - 2 \\times ${pT} + ${b * b} = ${bd2}$. On retrouve la règle du parallélogramme : $AC^2 + BD^2 = 2\\,AB^2 + 2\\,AD^2$.` : "")
    };
  };

  const SC_NOMS = [["A", "B", "C"], ["E", "F", "G"], ["R", "S", "T"], ["K", "L", "N"], ["D", "E", "F"], ["M", "N", "P"]];
  // Triangles entiers [b, c, a] dont l'angle en A mesure 60° ou 120° (a² = b² + c² ∓ bc)
  const SC_TRI = { 60: [], 120: [] };
  for (let b = 2; b <= 16; b++) for (let c = 2; c <= 16; c++) [60, 120].forEach((A) => { const a2 = b * b + c * c + (A === 60 ? -b * c : b * c), a = Math.round(Math.sqrt(a2)); if (b !== c && a * a === a2) SC_TRI[A].push([b, c, a]); });
