    const traits = (o.curves || []).map((c) => { const t = []; for (let k = 0; k <= 64; k++) { const x = c.a + ((c.b - c.a) * k) / 64, y = c.f(x); if (isFinite(y)) t.push([X(x), Y(Math.max(o.ymin - 1e3 * (o.ymax - o.ymin), Math.min(o.ymax + 1e3 * (o.ymax - o.ymin), y)))]); } return t; });
    (o.chemins || []).forEach((ch) => traits.push(ch.map(([x, y]) => [X(x), Y(y)])));
    (o.hlines || []).forEach((h) => traits.push([[padL, Y(h.y)], [W - pad, Y(h.y)]]));
    (o.fleches || []).forEach((f) => traits.push([[X(f.x1), Y(f.y1)], [X(f.x2), Y(f.y2)]]));
    (o.bars || []).forEach((b) => traits.push([[X(b.x), Y(y0)], [X(b.x), Y(b.y)]]));
    traits.push([[y0 !== 0 && x0 > o.xmin ? X(x0) : padL, Y(y0)], [W - pad, Y(y0)]], [[X(x0), pad], [X(x0), x0 !== 0 && y0 > o.ymin ? Y(y0) : H - padB]]);
    traits.forEach((t) => { t.b = [Math.min(...t.map((p) => p[0])), Math.min(...t.map((p) => p[1])), Math.max(...t.map((p) => p[0])), Math.max(...t.map((p) => p[1]))]; });
