    for (let x = Math.ceil(o.xmin / xe) * xe; x <= o.xmax - xs / 2; x += xe) if (Math.abs(x) > 1e-9) { const w = larg(nbr(x), 10); prises.push([X(x) - w / 2 - 2, Y(y0) + 3, X(x) + w / 2 + 2, Y(y0) + 16]); }
    for (let y = Math.ceil(o.ymin / ye) * ye; y <= o.ymax - ys / 2; y += ye) if (Math.abs(y) > 1e-9) { const w = larg(nbr(y), 10); prises.push([gy - w - 2, Y(y) - 6, gy + 2, Y(y) + 7]); }
    if (x0 === 0 && y0 === 0) prises.push([X(0) - 12, Y(0) + 3, X(0) - 2, Y(0) + 16]);
    (o.points || []).forEach((p) => {
      prises.push([X(p.x) - 5, Y(p.y) - 5, X(p.x) + 5, Y(p.y) + 5]);
      if (p.label && !p.auto) { const w = larg(p.label, 11); prises.push(p.gauche ? [X(p.x) - 9 - w, Y(p.y) - 17, X(p.x) - 7, Y(p.y) - 2] : [X(p.x) + 5, Y(p.y) - 17, X(p.x) + 7 + w, Y(p.y) - 2]); }
    });
