    if (o.ylabel) { const w = larg(o.ylabel, 11); prises.push([X(x0) + 5, pad - 3, X(x0) + 7 + w, pad + 12]); }
    (o.hlines || []).forEach((h) => { if (h.label && !h.auto) { const w = larg(h.label, 11); prises.push([W - pad - 3 - w, Y(h.y) - 16, W - pad - 1, Y(h.y) - 1]); } });
    (o.marques || []).forEach((m) => { const w = larg(m.texte, 11); prises.push([X(m.x) - w / 2 - 1, Y(m.y) - 11, X(m.x) + w / 2 + 1, Y(m.y) + 4]); });
    (o.curves || []).forEach((c) => { if (c.label && !c.auto) { const lx = c.lx !== undefined ? c.lx : c.b, w = larg(c.label, 13), x = X(lx) + (c.dx || -4), y = Y(c.f(lx)) + (c.dy || -8); prises.push([x - w - 1, y - 12.5, x + 1, y + 4]); } });
