    return graph(Object.assign({ xmin: -0.7, xmax: Math.max(...ks) + 0.8, ymin: Math.floor(lo / ystep) * ystep - ystep / 2, ymax: Math.ceil(hi / ystep) * ystep + ystep / 2, ystep, padL: 34, h: 220, bars: ks.map((x, i) => ({ x, y: vs[i] })) }, o));
