  FIGURES["cnt-meth-unique"] = () => { const f = (x) => x ** 3 + 2 * x - 1; return graph({ xmin: -1.2, xmax: 1.4, ymin: -4.2, ymax: 3.6, xstep: 0.5, padL: 26, h: 250, curves: [{ f, a: -1, b: 1.2, closed: false, label: "C<tspan class=\"sub\" dy=\"3\">f</tspan>", lx: 1.2, dx: -6, dy: -2 }], points: [{ x: 0, y: -1, label: "f(0) = −1", gauche: true }, { x: 1, y: 2, label: "f(1) = 2", gauche: true }, { x: cntRacine(f, 0, 1), y: 0, label: "α" }], aria: "Courbe strictement croissante de f(x) = x³ + 2x − 1 : elle passe de −1 en 0 à 2 en 1 et coupe l'axe des abscisses une seule fois, en α" }); };
