    let u;
    if (r === "orth") { const ko = pick([1, 2, -1]); u = n1.map((x) => ko * x); }
    else if (r === "par") { do { u = espRandNZ(3); } while (espScal(u, n1) !== 0); }
    else { do { u = espRandNZ(3); } while (espScal(u, n1) === 0 || espCol(u, n1)); }
