  // Intégrale exacte d'un polynôme [a_n, …, a_0] entre a et b, sous forme N/12
  const itgDouze = (co, a, b) => { const deg = co.length - 1; return co.reduce((s, c, i) => { const p = deg - i; return s + (c * 12 / (p + 1)) * (b ** (p + 1) - a ** (p + 1)); }, 0); };
