    const [ca, cb] = o.courbe || [xa + 0.15, xb - 0.15]; // partie tracée de la courbe
    let lo = 0, hi = 0;
    for (let i = 0; i <= 80; i++) { const y = f(ca + ((cb - ca) * i) / 80); lo = Math.min(lo, y); hi = Math.max(hi, y); }
