  FIGURES["itg-meth-encadrer"] = () => graph({ xmin: -0.15, xmax: 1.35, ymin: -0.15, ymax: 3.1, xstep: 0.25, xetiq: 0.5, ystep: 0.5, yetiq: 1, h: 240, padL: 28, rects: [{ a: 0, b: 1, h: Math.E }], aires: [{ f: (x) => Math.exp(x * x), a: 0, b: 1 }], curves: [{ f: (x) => Math.exp(x * x), a: 0, b: 1.04, closed: false, label: "y = exp(x²)", lx: 0.72, dx: -8, dy: -10 }], hlines: [{ y: 1, label: "y = 1" }, { y: Math.E, label: "y = e" }], aria: "Sur [0 ; 1], la courbe de e^(x²) reste entre les droites y = 1 et y = e : l'aire sous la courbe est comprise entre celle du carré de côté 1 (aire 1) et celle du rectangle de hauteur e (aire e)" });
