  FIGURES["itg-qcm-entre"] = () => graph({ xmin: -0.4, xmax: 3.4, ymin: -0.5, ymax: 4.6, h: 240, curves: [{ f: (x) => x, a: 0, b: 3.4, closed: false, label: "y = x", lx: 1, dx: 44, dy: 18 }, { f: (x) => x * (4 - x), a: 0, b: 3.4, closed: false, label: "y = x(4 − x)", lx: 2, dx: 30, dy: -8 }], aires: [{ f: (x) => x * (4 - x), g: (x) => x, a: 0, b: 3 }], points: [{ x: 0, y: 0 }, { x: 3, y: 3, label: "(3 ; 3)" }], aria: "Domaine coloré entre la parabole y = x(4 − x), au-dessus, et la droite y = x, au-dessous, entre 0 et 3" });
