  FIGURES["trg-courbes"] = () => trgGraphe({ a: -Math.PI, b: 2 * Math.PI, ymin: -1.5, ymax: 1.9, q: 2, h: 220, curves: [{ f: Math.sin, a: -Math.PI, b: 2 * Math.PI, closed: false, label: "sin", lx: Math.PI / 2, dx: 10, dy: -10 }, { f: Math.cos, a: -Math.PI, b: 2 * Math.PI, closed: false, label: "cos", lx: 2 * Math.PI, dx: 2, dy: -10 }], aria: "Courbes des fonctions sinus et cosinus de −π à 2π : deux vagues de hauteur 1, décalées d'un quart de période ; elles se répètent tous les 2π" });
